#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

// Compute floor division (mathematical floor) for possibly negative numbers
static long floor_div(long a, long b, long *rem) {
    long q = a / b;
    long r = a % b;
    // Adjust when remainder has opposite sign to divisor to make remainder non‑negative
    if (r != 0 && ((r < 0) != (b < 0))) {
        q -= 1;
        r += b;
    }
    if (rem) *rem = r;
    return q;
}

int main(int argc, char **argv) {
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    char *end1, *end2;
    long a = strtol(argv[1], &end1, 10);
    long b = strtol(argv[2], &end2, 10);

    // Bad input if conversion failed or extra characters remain
    if (end1 == argv[1] || end2 == argv[2] || *end1 != '\0' || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    // Zero denominator – empty continued fraction
    if (b == 0) {
        puts("[]");
        return 0;
    }

    // Range check for denominator magnitude (as observed in the original binary)
    if (llabs(b) > 100000) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    // Normalise sign: keep denominator positive
    if (b < 0) {
        a = -a;
        b = -b;
    }

    // Compute continued‑fraction terms using the Euclidean algorithm
    long terms[200];
    int count = 0;
    long num = a;
    long den = b;
    while (den != 0) {
        if (count >= 200) { // more than 199 terms is considered an error
            puts("ERROR");
            return 0;
        }
        long rem;
        long q = floor_div(num, den, &rem);
        terms[count++] = q;
        num = den;
        den = rem;
    }

    // Output in the form [q0; q1, q2, ...]
    putchar('[');
    if (count > 0) {
        printf("%ld", terms[0]);
        if (count > 1) {
            printf("; ");
            for (int i = 1; i < count; ++i) {
                printf("%ld", terms[i]);
                if (i + 1 < count) {
                    printf(", ");
                }
            }
        }
    }
    puts("]");
    return 0;
}
